    ]
  },
  {
    "alert_id": "P003_ADSM_SCREEN_002",
    "title": "Neuropsychiatric symptoms not documented on aDSM screening form",
    "message": "Guidelines require asking patients about neuropsychiatric symptoms (bad dreams, suicidal thoughts, insomnia, headaches, anxiety, mood changes) at every monthly visit for EFV-containing regimens, and completing the adverse drug reaction (aDSM) form for reporting. This patient's insomnia and vivid dreams were noted in the assessment but no aDSM screening documentation or adverse event reporting appears in the record. Formal screening would also systematically cover suicidal ideation, which was only informally assessed today.",
    "issue_type": "monitoring_gap",
    "severity": "low",
    "recommended_action": "Complete the aDSM symptom checklist and submit the suspected ADR reporting form for this EFV-related neuropsychiatric event.",
    "citations": [
      {"page_number": 23, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p23_c2"},
      {"page_number": 22, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p22_c2"}
    ]
  },
  {
    "alert_id": "P003_MENTAL_HEALTH_SCREEN_003",
    "title": "No structured mental health or suicidality assessment documented",
    "message": "Guidelines note that suicidality remains a common concern and may require additional assessment, and recommend validated brief instruments such as the PHQ-2/PHQ-9, GAD-7, K-10, or AUDIT for diagnosing depression, anxiety, and substance use. This patient reports persistent insomnia with vivid dreams on EFV, and suicidality was only addressed with a single negative statement without any structured screening tool or documented mental health evaluation. Given EFV's association with depression and anxiety, a structured assessment is warranted.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Administer a validated screening instrument (e.g., PHQ-9, GAD-7) and perform formal suicidality assessment at this visit.",
